def transform(grid):
    from collections import Counter
    # The answer is the sparse color whose marks repeat in the same
    # positions across successive horizontal separator rows.
    sep_rows = [r for r, row in enumerate(grid) if all(x == 2 for x in row)]
    counts = Counter()
    for r in sep_rows:
        for x in grid[r]:
            if x != 2:
                counts[x] += 1
    return [[min(counts, key=lambda c: (counts[c], c))]]
